	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/teams/{team_id}/domains/{domain_id}", wrapper.ReleaseTeamDomain)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/authorizations", wrapper.IssueAuthorization)

	return m
